export const byId = Object.fromEntries(MOVIES.map((m) => [m.id, m]));

export const parseCast = (c) => {
  const [actor, character, img] = c.split('|');
  return { actor, character, img };
};

export const isUpcoming = (m, now = new Date()) => new Date(m.release) > now;

export const chronological = [...MOVIES].sort((a, b) => a.chronoOrder - b.chronoOrder);
export const byRelease = [...MOVIES].sort((a, b) => a.release.localeCompare(b.release));

// Films that list this one as a prerequisite -> "watch next"
export const leadsInto = (id) => MOVIES.filter((m) => m.before.includes(id));
